["Collect 10 Shadowshard Fragments from Maraudon and return them to Archmage Tervosh in Theramore on the coast of Dustwallow Marsh."]="收集10 Shadowshard Fragments from Maraudon，并return them to Archmage Tervosh in Theramore on the coast of Dustwallow Marsh。",
["Collect 10 Shadowshard Fragments from Maraudon and return them to Uthel'nay in Orgrimmar."]="从玛拉顿收集10块暗影碎片并带回给奥格瑞玛的乌瑟尔奈。",
