["Collect 25 Intact Limbs within The Ruins of Lordaeron for Morbin Lightbane in the Undercity."]="在洛丹伦废墟中收集25条完整的肢体，交给幽暗城的摩宾·灭光。",
["Collect 5 I'lalai Fetishes from trolls in the Drowned City."]="从沉没之城的巨魔手中收集5件伊拉莱神像。",
