["Collect 8 Dwarven Heirlooms from the Hall of Thanes."]="从领主大厅收集8件矮人传家宝。",
["Collect a Fel Infused Blossom from the City of Dalaran for Shylamiir in Stormwind City."]="在达拉然城收集一朵注入邪能的花朵，交给暴风城的希拉米尔。",
["Collect the Arcane Mote for the Image of Archmage Modera near the City of Dalaran."]="收集奥术微尘，交给达拉然城附近的大法师莫德拉的影像。",
["Collect the Arcane Mote in the City of Dalaran for Magus Wordeen Voidglare in Tarren Mill."]="在达拉然城收集奥术微尘，交给塔伦米尔的法师沃丁·虚空凝视。",
["Collect the Founding of Dalaran from the City of Dalaran for Rexxie Copperclutch near the sewer entrance."]="从达拉然城收集《达拉然的建立》，交给下水道入口附近的雷克西·铜手。",
["Collect the Head of the Baron in the Ruins of Lordaeron and bring it back to Captain Truman."]="收集洛丹伦废墟中的男爵头颅，并带回给杜鲁门队长。",
