["Find 3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment and return them to Doan Karhan in the Barrens."]="找到3块索兰鲁克碎片和1块大索兰鲁克碎片，并将它们带给贫瘠之地的多安·卡汉。",
