["Find Ranshalla"]="兰莎尔拉",
["Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke."]="在the Scholomance找到Ras Frostwhisper。",
["Find Starfall in Winterspring and speak with Wynd Nightchaser."]="在Winterspring and speak with Wynd Nightchaser找到Starfall。",
["Find The Beginnings of the Undead Threat, and return it to Parqual Fintallas in Undercity."]="在Undercity找到The Beginnings of the Undead Threat, and return it to Parqual Fintallas。",
["Find The Eye of Bhossca inside of the Scarlet Monastery. Then, return it to C's dead drop near Pyrewood Village. You must complete the job alone."]="在血色修道院内找到博斯卡之眼。然后将其送回焚木村附近的C的秘密接头点。你必须独自完成这项任务。",
["Find The Horn of Xelthos inside of Shadowfang Keep. Then, return it to C's dead drop near Pyrewood Village. You must complete the job alone."]="在影牙城堡内找到泽尔托斯之角。然后将其送回焚木村附近的C的秘密接头点。你必须独自完成这项任务。",
["Find a clue as to the gems' whereabouts in the depths of Uldaman."]="在奥达曼深处寻找宝石下落的线索。",
["Find a way into Dalaran along the Lordamere Lake."]="沿着洛丹米尔湖寻找进入达拉然的通道。",
["Find and return Treshala's Pendant to Treshala Fallowbrook in Darnassus."]="找到特雷沙拉的吊坠，并将其带回给达纳苏斯的特雷沙拉·法洛布鲁克。",
["Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic."]="找到并杀掉傀儡统帅阿格曼奇，将他的头交给鲁特维尔。你还需要从守卫着阿格曼奇的狂怒傀儡和战斗傀儡身上收集10块完整的元素核心。",
["Find the Black Guard Swordsmith in Stratholme and destroy him. Recover the Insignia of the Black Guard and return to Seril Scourgebane."]="在Stratholme and destroy him找到the Black Guard Swordsmith。",
["Find the Deathstalker Adamant and Deathstalker Vincent."]="找到亡灵哨兵阿达曼特和亡灵哨兵文森特。",
["Find the Felvine in Dire Maul and acquire a shard from it. Chances are you'll only be able to procure one with the demise of Alzzin the Wildshaper. Use the Reliquary of Purity to securely seal the shard inside, and return it to Rabine Saturna in Nighthaven, Moonglade."]="在厄运之槌中找到魔藤并从中获取一块碎片。通常你必须击败荒野变形者奥兹恩才能获得。使用纯洁圣物箱密封碎片，并带回给月光林地永夜港的拉宾·萨图纳。",
["Find the Gems"]="寻找宝石",
