["Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel."]="杀死20只瘟疫幼龙，然后回到圣光之愿礼拜堂的贝蒂娜·比格辛克身边。",
["Kill 6 Dalaran Summoners and 12 Elemental Slaves, then return to Magus Voidglare in Tarren Mill."]="杀死6 Dalaran Summoners并12 Elemental Slaves, then return to Magus Voidglare in Tarren Mill。",
["Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs."]="击败8名剃刀沼泽近卫兵、8名剃刀沼泽织棘者和8名死首信徒，然后回到剃刀高地入口附近的米里安·月歌处。",
