["Travel to Lakeshire and deliver Helendis Riverhorn's Letter to Magistrate Solomon."]="前往湖畔镇，将赫伦迪斯·河角的信交给所罗门镇长。",
["Travel to Stormwind City and venture to the city gates. Speak with Squire Rowe so that he may let Marshal Windsor know that you have arrived."]="前往Stormwind City并venture to the city gates。",
["Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive."]="前往Stratholme并find Archivist Galford of the Scarlet Crusade。",
["Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground."]="前往斯坦索姆寻找米奈希尔的礼物。将纪念信物放置在邪恶的土地上。",
["Travel to Stratholme and slay Ramstein the Gorger. Take his head as a souvenir for Nathanos."]="前往Stratholme并slay Ramstein the Gorger。",
["Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid."]="前往Stratholme, in the north. Search the supply crates that litter the city并recover 5 Stratholme Holy Water。",
["Travel to Winterspring and find Haleh. Give her Awbee's scale."]="前往冬泉谷找到哈莱。把奥比的鳞片交给她。",
["Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence."]="前往the Warpwood Quarter of Dire Maul并slay the water elemental, Hydrospawn。",
["Travel to the Wetlands and meet the Deathstalker Agent in the hills above the Dragonmaw camp."]="前往湿地，在龙喉营地上方的山丘与亡灵哨兵密探汇合。",
